 "content": "from copy import deepcopy


def transform(grid):
    """Copy the colored pattern onto every translated all-zero occurrence."""
    h, w = len(grid), len(grid[0])
    colors = {v for row in grid for v in row if v not in (0, 4, 9)}
    if len(colors) != 1:
        return deepcopy(grid)
    color = next(iter(colors))
    points = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == color]
    if not points:
        return deepcopy(grid)
    r0 = min(r for r, c in points)
    c0 = min(c for r, c in points)
    shape = [(r-r0, c-c0) for r, c in points]
    out = deepcopy(grid)
    placements = []
    for dr in range(-r0, h-r0):
        for dc in range(-c0, w-c0):
            cells = [(r0+dr+sr, c0+dc+sc) for sr, sc in shape]
            if all(0 <= r < h and 0 <= c < w and grid[r][c] == 0 for r, c in cells):
                placements.append(cells)
    for cells in placements:
        for r, c in cells:
            out[r][c] = color
    return out


if __name__ == "__main__":
    import json, sys
    print(json.dumps(transform(json.load(sys.stdin))))
